('yz450f', 'Yamaha YZ450F', 2025, '4T'::engine_type, 'COMPETICION'::category, 450, 1049900, 3, 'Motor 450cc 4T invertido de máxima compresión con inyección DFI, App Power Tuner integrada y chasis de viga bilateral de aluminio rediseñado.', 'Best Seller MXGP', '[{"label":"Cilindrada","value":"450 cc"},{"label":"Peso en orden de marcha","value":"109 kg"},{"label":"Horquilla","value":"KYB AOS"}]'::jsonb, '[{"title":"01. Grupo propulsor e inyección DOHC","rows":[{"label":"Tipo de motor","value":"4T monocilíndrico DOHC invertido"},{"label":"Válvulas","value":"4 válvulas de titanio"},{"label":"Relación de compresión","value":"13,0 : 1"},{"label":"Alimentación","value":"Inyección Mikuni Ø 44 mm"}],"note":"Culata invertida de alto flujo con admisión frontal directa y pistón forjado aligerado."},{"title":"02. Chasis de doble viga de aluminio y suspensión KYB","rows":[{"label":"Bastidor","value":"Viga de aluminio hidroformado"},{"label":"Horquilla delantera","value":"KYB SSS 48 mm"},{"label":"Suspensión trasera","value":"Monoamortiguador KYB"},{"label":"Freno delantero","value":"Disco hidráulico Nissin 270 mm"}]},{"title":"03. Geometría, depósito y dimensiones","rows":[{"label":"Capacidad del depósito","value":"6,2 L"},{"label":"Altura del asiento","value":"965 mm"},{"label":"Distancia entre ejes","value":"1.480 mm"},{"label":"Distancia mínima al suelo","value":"350 mm"}]}]'::jsonb, '[{"src":"/images/yz450f-lateral.jpg","alt":"Yamaha YZ450F 2025, vista lateral","width":512,"height":279},{"src":"/images/yz450f-perfil.jpg","alt":"Yamaha YZ450F 2025, perfil","width":512,"height":512},{"src":"/images/yz450f-motor.jpg","alt":"Motor invertido de la Yamaha YZ450F","width":512,"height":279},{"src":"/images/yz450f-escape.jpg","alt":"Línea de escape de la Yamaha YZ450F","width":512,"height":279},{"src":"/images/yz450f-cockpit.jpg","alt":"Manillar y app Power Tuner de la Yamaha YZ450F","width":512,"height":279}]'::jsonb, true, 1),
('yz250f', 'Yamaha YZ250F', 2025, '4T'::engine_type, 'COMPETICION'::category, 250, 939900, 4, 'Motor 250cc 4T invertido de altísimo régimen de giro, nuevo conducto de admisión y suspensión KYB SSS líder en su categoría.', 'Campeona MX2', '[{"label":"Cilindrada","value":"250 cc"},{"label":"Peso en orden de marcha","value":"105 kg"},{"label":"Suspensión","value":"KYB SSS"}]'::jsonb, '[{"title":"01. Grupo propulsor","rows":[{"label":"Tipo de motor","value":"4T monocilíndrico DOHC invertido"},{"label":"Válvulas","value":"4 válvulas de titanio"},{"label":"Relación de compresión","value":"13,8 : 1"},{"label":"Alimentación","value":"Inyección Keihin Ø 44 mm"}]},{"title":"02. Chasis y suspensión","rows":[{"label":"Bastidor","value":"Viga de aluminio bilateral"},{"label":"Horquilla delantera","value":"KYB SSS 48 mm"},{"label":"Suspensión trasera","value":"Monoamortiguador KYB"},{"label":"Freno delantero","value":"Disco hidráulico 270 mm"}]},{"title":"03. Dimensiones","rows":[{"label":"Capacidad del depósito","value":"6,2 L"},{"label":"Altura del asiento","value":"970 mm"},{"label":"Distancia entre ejes","value":"1.475 mm"},{"label":"Distancia mínima al suelo","value":"335 mm"}]}]'::jsonb, '[{"src":"/images/yz250f.jpg","alt":"Yamaha YZ250F 2025 trazando una curva en arena","width":512,"height":279}]'::jsonb, false, 2),
